-- NULL must not pass required fixed object evidence or a generation result association.
ALTER TABLE generation_media_outputs ADD CONSTRAINT generated_source_complete CHECK((source->>'kind'='fixture_object' AND jsonb_typeof(source->'object')='object' AND source->'object'->>'key' ~ '^(staging|originals)/[a-f0-9-]{36}$' AND source->>'sha256' ~ '^[a-f0-9]{64}$' AND source->>'mime' IN ('image/png','image/jpeg','image/webp') AND (source->'object'->>'bytes')::bigint BETWEEN 1 AND 268435456 AND length(source->'object'->>'versionId') BETWEEN 1 AND 1024 AND source->'object'->>'versionId'<>'null' AND jsonb_typeof(output_options)='object' AND output_options->>'resolution' ~ '^[0-9]+x[0-9]+$') IS TRUE);
